$ErrorActionPreference = 'Stop'
if (-not $IsWindows -or $PSVersionTable.PSVersion.Major -lt 7) { throw 'Windows pwsh 7 required' }
$base = '80d56fd1d6ef666eefe804be7f38de4742dcec43'
$path = '.github/actions/run-duplicate-function-check/Invoke-DcoirDuplicateFunctionCheck.ps1'
$checkout = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
$blob = git -C $checkout rev-parse "${base}:$path"
if ($LASTEXITCODE -ne 0 -or $blob -ne '6ba6bcc1b8f028399fa91d53f24901a7d20ae905') { throw 'Baseline blob mismatch' }
$source = (git -C $checkout show "${base}:$path") -join "`n"
if ($LASTEXITCODE -ne 0) { throw 'Baseline read failed' }
$tokens = $null; $errors = $null
$ast = [System.Management.Automation.Language.Parser]::ParseInput($source,[ref]$tokens,[ref]$errors)
$defs = @($ast.EndBlock.Statements | Where-Object { $_ -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $_.Name -in @('Resolve-CollectorReportPath','ConvertTo-MarkdownTableCell') })
if ($errors.Count -ne 0 -or $defs.Count -ne 2 -or @($defs.Name | Sort-Object -Unique).Count -ne 2) { throw 'Baseline AST mismatch' }
$start = (Get-Location).Path
$scratch = Join-Path ([IO.Path]::GetTempPath()) ('dcoir-608-' + [guid]::NewGuid().ToString('N'))
$owned = $false; $link = $null
try {
    New-Item -ItemType Directory -Path $scratch | Out-Null; $owned = $true
    $repo = Join-Path $scratch 'repo'; $outside = Join-Path $scratch 'outside'
    $collector = Join-Path $repo 'project_sources/collector'
    New-Item -ItemType Directory -Path $collector,$outside -Force | Out-Null
    $legacy = Join-Path $scratch 'legacy.ps1'
    [IO.File]::WriteAllText($legacy, (($defs | ForEach-Object { $_.Extent.Text }) -join "`n`n"))
    Set-Location -LiteralPath $repo
    $repoRoot = [IO.Path]::GetFullPath((Get-Location).Path).TrimEnd([char]'\',[char]'/') + [IO.Path]::DirectorySeparatorChar
    . $legacy
    $safe = Resolve-CollectorReportPath 'project_sources/collector/report.json' 'JSON' '.json'
    if ($safe.FullPath -ne (Join-Path $collector 'report.json')) { throw 'Safe control failed' }
    $reason = $null
    try { $null = Resolve-CollectorReportPath 'project_sources/collector/../report.json' 'JSON' '.json' } catch { $reason = $_.Exception.Message }
    if ($reason -notlike '*must not contain traversal*') { throw 'Traversal control failed' }
    Write-Output "BASELINE=$base BLOB=$blob PWSH=$($PSVersionTable.PSVersion) SAFE_AND_REJECT_CONTROLS=PASS"
    $link = Join-Path $collector 'probe-junction'
    New-Item -ItemType Junction -Path $link -Target $outside | Out-Null
    $item = Get-Item -LiteralPath $link -Force
    if ($item.LinkType -ne 'Junction' -or [string](@($item.Target)[0]) -ne $outside) { throw 'Junction fixture mismatch' }
    $result = $null; $reason = $null
    try { $result = Resolve-CollectorReportPath 'project_sources/collector/probe-junction/report.json' 'JSON' '.json' } catch { $reason = $_.Exception.Message }
    if ($null -ne $result) {
        Write-Output "CONTAINMENT_DEFECT: accepted=$($result.FullPath); junction_target=$outside"
    } else { Write-Output "JUNCTION_REJECTED: $reason" }
    if (Test-Path -LiteralPath (Join-Path $outside 'report.json')) { throw 'Unexpected fixture report write' }
} finally {
    Set-Location -LiteralPath $start
    if ($owned) {
        if ($link -and (Test-Path -LiteralPath $link)) { [IO.Directory]::Delete($link,$false) }
        if ($link -and (Test-Path -LiteralPath $link)) { throw 'Junction cleanup failed; refusing recursive cleanup' }
        Remove-Item -LiteralPath $scratch -Recurse -Force
    }
}
Write-Output 'PROBE_FINISHED_NO_REPORT_WRITES'

